import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"繁荣度与活跃度","description":"","frontmatter":{},"headers":[],"relativePath":"towns/Advancements.md","filePath":"towns/Advancements.md"}'),o={name:"towns/Advancements.md"};function n(h,t,s,c,i,l){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="繁荣度与活跃度" tabindex="-1">繁荣度与活跃度 <a class="header-anchor" href="#繁荣度与活跃度" aria-label="Permalink to &quot;繁荣度与活跃度&quot;">​</a></h1><p>联盟的<strong>活跃度</strong>（繁荣度）反映联盟成员的活跃程度，由成员在联盟领地内的活动积累而来，<strong>无法用钻石购买</strong>。</p><h2 id="活跃度来源" tabindex="-1">活跃度来源 <a class="header-anchor" href="#活跃度来源" aria-label="Permalink to &quot;活跃度来源&quot;">​</a></h2><p>成员在联盟领地内的活动会为联盟积累活跃度：</p><table tabindex="0"><thead><tr><th>活动</th><th>说明</th></tr></thead><tbody><tr><td>生产</td><td>在联盟领地内采集/耕种等生产行为</td></tr><tr><td>狩猎</td><td>在联盟领地内击杀生物</td></tr><tr><td>驻留</td><td>在联盟领地内停留</td></tr><tr><td>访客</td><td>联盟领地接待的访客</td></tr></tbody></table><h2 id="繁荣度档位" tabindex="-1">繁荣度档位 <a class="header-anchor" href="#繁荣度档位" aria-label="Permalink to &quot;繁荣度档位&quot;">​</a></h2><p>联盟活跃度达到阈值后解锁更高档位，领地之心效果与展示随之升级：</p><table tabindex="0"><thead><tr><th>档位</th><th>图标</th><th>活跃度阈值</th></tr></thead><tbody><tr><td><strong>铜锭</strong></td><td>铜锭</td><td>200</td></tr><tr><td><strong>铁锭</strong></td><td>铁锭</td><td>450</td></tr><tr><td><strong>金锭</strong></td><td>金锭</td><td>800</td></tr><tr><td><strong>下界之星</strong></td><td>下界之星</td><td>1200</td></tr><tr><td>沉眠</td><td>灰色染料</td><td>长期无活跃</td></tr></tbody></table><h2 id="查看繁荣度" tabindex="-1">查看繁荣度 <a class="header-anchor" href="#查看繁荣度" aria-label="Permalink to &quot;查看繁荣度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/gclaim prosperity</code></td><td>查看联盟繁荣度详情</td></tr><tr><td><code>/gclaim top</code></td><td>查看全服活跃榜</td></tr></tbody></table><h2 id="领地之心" tabindex="-1">领地之心 <a class="header-anchor" href="#领地之心" aria-label="Permalink to &quot;领地之心&quot;">​</a></h2><p>把满级信标注册为联盟的<strong>领地之心</strong>（灯塔），可解锁传送与特效：</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/gclaim heart register</code></td><td>把脚下满级信标注册为领地之心</td></tr><tr><td><code>/gclaim heart unregister</code></td><td>注销领地之心</td></tr><tr><td><code>/gclaim heart effect</code></td><td>查看/切换特效</td></tr><tr><td><code>/gclaim heart info</code></td><td>查看领地之心信息</td></tr><tr><td><code>/gclaim heart public on/off</code></td><td>开关公开传送（银锭档位以上）</td></tr></tbody></table><h2 id="与联盟等级的关系" tabindex="-1">与联盟等级的关系 <a class="header-anchor" href="#与联盟等级的关系" aria-label="Permalink to &quot;与联盟等级的关系&quot;">​</a></h2><p>联盟活跃度会联动上报给<a href="./#等级与经验">联盟</a>系统转化为联盟经验，帮助联盟升级、提升成员上限——越活跃的联盟越强大。</p>',15)])])}const p=d(o,[["render",n]]);export{m as __pageData,p as default};
